/**
 * Quotes the React Native bundling script path in the generated Xcode project.
 *
 * The prebuild template emits the bundle phase as:
 *
 *     `"$NODE_BINARY" --print "...react-native-xcode.sh"`
 *
 * The backticks substitute the path, and the shell then executes the *result*
 * unquoted. On a checkout whose path contains a space — say
 * `/Volumes/T7 Shield Data/...` — that splits into a command plus arguments and
 * the build dies with `No such file or directory: /Volumes/T7`.
 *
 * `ios/` is regenerated by `expo prebuild`, so this cannot live in a patch file;
 * it has to run on every prebuild.
 *
 * Delete this plugin if the project ever moves to a path without spaces.
 */
const { withXcodeProject } = require('@expo/config-plugins')

const UNQUOTED =
  '`"$NODE_BINARY" --print "require(\'path\').dirname(require.resolve(\'react-native/package.json\')) + \'/scripts/react-native-xcode.sh\'"`'

const QUOTED = [
  'REACT_NATIVE_XCODE_SCRIPT="$("$NODE_BINARY" --print "require(\'path\').dirname(require.resolve(\'react-native/package.json\')) + \'/scripts/react-native-xcode.sh\'")"',
  '/bin/sh "$REACT_NATIVE_XCODE_SCRIPT"',
].join('\n')

module.exports = function withSafeBundleScriptPaths(config) {
  return withXcodeProject(config, (mod) => {
    const phases = mod.modResults.hash.project.objects.PBXShellScriptBuildPhase
    if (!phases) return mod

    let patched = 0
    for (const key of Object.keys(phases)) {
      const phase = phases[key]
      // Skip the `_comment` sibling entries pbxproj parsers add.
      if (!phase || typeof phase !== 'object' || !phase.shellScript) continue

      // `shellScript` is stored as a quoted, escaped pbxproj string.
      const script = JSON.parse(phase.shellScript)
      if (!script.includes(UNQUOTED)) continue

      phase.shellScript = JSON.stringify(script.replace(UNQUOTED, QUOTED))
      patched += 1
    }

    if (patched === 0) {
      // Loud on purpose: a silent no-op here means the build breaks later with a
      // far less obvious error.
      console.warn(
        '[withSafeBundleScriptPaths] Found no unquoted bundle script phase. ' +
          'The prebuild template probably changed — re-check the fix.'
      )
    }
    return mod
  })
}
